    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton2&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;2&#39;);&quot; onmouseout=&quot;outButton(&#39;2&#39;);&quot; onclick=&quot;expandMenu(&#39;2&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Personnage-Mythique.html&quot; title=&quot;Cr&#233;ation d&amp;#39;un personnage mythique&quot;&gt;Cr&#233;ation d&#39;un personnage mythique&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;2&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;Voie de l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Archimage-Mythique.html&quot; title=&quot;L&amp;#39;archimage mythique&quot;&gt;archimage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-Voie-De-Larchimage-Mythique.html&quot; title=&quot;Aptitudes de voie de l&amp;#39;archimage mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Champion-Mythique.html&quot; title=&quot;Le champion mythique&quot;&gt;champion&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Champion-Mythique.html&quot; title=&quot;Aptitudes de voie du champion mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Filou-Mythique.html&quot; title=&quot;Le filou mythique&quot;&gt;filou&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Filou-Mythique.html&quot; title=&quot;Aptitudes de voie du filou mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Hi&#233;rophante-Mythique.html&quot; title=&quot;Le hi&#233;rophante mythique&quot;&gt;hi&#233;rophante&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Hi&#233;rophante-Mythique.html&quot; title=&quot;Aptitudes de voie du hi&#233;rophante mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Mar&#233;chal-Mythique.html&quot; title=&quot;Le mar&#233;chal mythique&quot;&gt;mar&#233;chal&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Mar&#233;chal-Mythique.html&quot; title=&quot;Aptitudes de voie du mar&#233;chal mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Protecteur-Mythique.html&quot; title=&quot;Le protecteur mythique&quot;&gt;protecteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Protecteur-Mythique.html&quot; title=&quot;Aptitudes de voie du protecteur mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-Voie-Universelles-Mythique.html&quot; title=&quot;Aptitudes de voie universelles Mythique&quot;&gt;Aptitudes de voie universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Des-Enfants-Divins-Mythiques.html&quot; title=&quot;Aptitudes de voie des enfants divins mythiques&quot;&gt;Aptitudes de voie des enfants divins&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton3&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;3&#39;);&quot; onmouseout=&quot;outButton(&#39;3&#39;);&quot; onclick=&quot;expandMenu(&#39;3&#39;);&quot; /&gt;
&lt;/div&gt;Options de personnage mythiques&amp;emsp;
        &lt;ul ID=&quot;3&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Mythiques.html&quot; title=&quot;Les dons mythiques&quot;&gt;Les dons mythiques&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons-Mythiques.html&quot; title=&quot;Dons mythiques&quot;&gt;tableau&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-L&#233;gendaires.html&quot; title=&quot;Objets l&#233;gendaires&quot;&gt;Les objets l&#233;gendaires&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Magiques-Mythiques.html&quot; title=&quot;Les objets magiques mythiques&quot;&gt;Les objets magiques mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Mythiques.html&quot; title=&quot;Les sorts mythiques&quot;&gt;Les sorts mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton4&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;4&#39;);&quot; onmouseout=&quot;outButton(&#39;4&#39;);&quot; onclick=&quot;expandMenu(&#39;4&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html&quot; title=&quot;Les monstres mythiques&quot;&gt;Les monstres mythiques&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;4&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types-Simples-De-Cr&#233;atures-Mythiques.html&quot; title=&quot;Arch&#233;types simples de cr&#233;atures mythiques&quot;&gt;Arch&#233;types simples de cr&#233;atures mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique.html&quot; title=&quot;Construire une cr&#233;ature mythique&quot;&gt;Construire une cr&#233;ature mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;Le sous-type mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-De-Monstres-Mythiques-Universelles.html&quot; title=&quot;R&#232;gles de monstres mythiques universelles&quot;&gt;R&#232;gles de monstres mythiques universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;valuer-Les-Statistiques-Des-Monstres.html&quot; title=&quot;&#201;valuer les statistiques des monstres&quot;&gt;&#201;valuer les statistiques des monstres&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Liste-Alphab&#233;tique-Des-Monstres-Mythiques.html&quot; title=&quot;Liste alphab&#233;tique des monstres mythiques&quot;&gt;Liste des monstres mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Campagnes mythiques (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Mythic Adventures, Mythic Origins/Campagnes mythiques&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoCMy.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;En plus de l’arch&#233;type simple de cr&#233;ature mythique, il existe deux autres mani&#232;res de cr&#233;er un nouveau monstre mythique. La premi&#232;re consiste &#224; prendre un monstre existant, &#224; lui rajouter le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;sous-type mythique&lt;/a&gt; et les aptitudes indiqu&#233;es pour ce sous-type. La seconde consiste &#224; cr&#233;er un tout nouveau monstre avec le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;sous-type mythique&lt;/a&gt; et d’int&#233;grer les aptitudes suppl&#233;mentaires au monstre final.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Modifier un monstre existant&lt;a class=&quot;headeranchor&quot; id=&quot;Modifier_un_monstre_existant_0&quot; href=&quot;#Modifier_un_monstre_existant_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Il est tr&#232;s simple de cr&#233;er un monstre mythique &#224; partir d’un monstre ordinaire. Il vous suffit de suivre ces &#233;tapes.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 1 : d&#233;terminer le &lt;a class=&quot;pagelink&quot; href=&quot;Rang-Mythique.html&quot; title=&quot;Rang mythique&quot;&gt;rang mythique&lt;/a&gt; (RMy).&lt;/b&gt; Divisez le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; de votre monstre par 2 pour obtenir son &lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html#RANGMYTHIQUE&quot; title=&quot;Les monstres mythiques&quot;&gt;rang mythique&lt;/a&gt; approximatif. Si le r&#233;sultat obtenu n’est pas un nombre entier, vous avez toute libert&#233; de choisir le RMy. Par exemple, si votre monstre est une chim&#232;re FP 7, 7 divis&#233; par 2 donnant 3,5, cela signifie que vous pouvez lui attribuer un RMy 3 ou un RMy 4. Il est plus facile de commencer avec un RMy plus bas puisque vous pouvez toujours l’augmenter plus tard si vous avez besoin d’un monstre un peu plus puissant.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 2 : ajouter le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;sous-type mythique&lt;/a&gt;.&lt;/b&gt; Les modifications apport&#233;es aux valeurs de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques.html&quot; title=&quot;Les caract&#233;ristiques&quot;&gt;caract&#233;ristiques&lt;/a&gt; de la cr&#233;ature, &#224; ses points de vie et &#224; d’autres de ses statistiques de jeu d&#233;pendent du RMy de votre monstre.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 3 : ajouter les aptitudes mythiques suppl&#233;mentaires.&lt;/b&gt; Comme indiqu&#233; dans le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;sous-type mythique&lt;/a&gt;, le monstre gagne un nombre d’aptitudes mythiques &#233;gal &#224; son RMy +1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 4 : &#233;valuer le monstre avec son &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; final.&lt;/b&gt; Le FP final de votre monstre est &#233;gal &#224; son FP de d&#233;part + son RMy/2 (arrondi &#224; l’inf&#233;rieur ; 1 au minimum). Consultez &lt;a class=&quot;pagelink&quot; href=&quot;&#201;valuer-Les-Statistiques-Des-Monstres.html#STATMONSTRESMYTHIQUEPARFP&quot; title=&quot;&#201;valuer les statistiques des monstres&quot;&gt;statistiques des monstres par FP&lt;/a&gt; pour d&#233;terminer si les aptitudes du monstre sont appropri&#233;es au niveau de difficult&#233; correspondant &#224; son FP final. Si les aptitudes mythiques de la cr&#233;ature compl&#232;tent particuli&#232;rement bien ses aptitudes &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Nonmythique.html&quot; title=&quot;non-mythique&quot;&gt;non-mythiques&lt;/a&gt;, alors la cr&#233;ature mythique est sans doute trop puissante pour son FP final. Si les aptitudes mythiques de la cr&#233;ature ne se combinent pas avec ses aptitudes non-mythiques, la cr&#233;ature n’est sans doute pas assez puissante pour son FP final. Si jamais l’un de ces deux cas de figure se pr&#233;sente, proc&#233;dez aux ajustements n&#233;cessaires pour que la cr&#233;ature corresponde au FP vis&#233;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;indent&quot; style=&quot;margin: 0px; padding: 0px; padding-left: 15px&quot;&gt;Si la cr&#233;ature n’est pas assez puissante et que vous avez arrondi son RMy &#224; l’inf&#233;rieur au cours de la premi&#232;re &#233;tape, vous pouvez alors l’arrondir au sup&#233;rieur &#224; la place (ajustez les modificateurs apport&#233;s par le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;sous-type mythique&lt;/a&gt;). Si la cr&#233;ature est trop puissante et que vous avez arrondi son RMy au sup&#233;rieur au cours de la premi&#232;re &#233;tape, vous pouvez alors l’arrondir &#224; l’inf&#233;rieur &#224; la place (ajustez les modificateurs apport&#233;s par le sous-type mythique).&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;indent&quot; style=&quot;margin: 0px; padding: 0px; padding-left: 15px&quot;&gt;Une fois que les aptitudes et les statistiques de la cr&#233;ature correspondent &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt;, vous avez termin&#233;.&lt;/div&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Cr&#233;er un nouveau monstre&lt;a class=&quot;headeranchor&quot; id=&quot;Cr&#233;er_un_nouveau_monstre_1&quot; href=&quot;#Cr&#233;er_un_nouveau_monstre_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Il est particuli&#232;rement difficile de cr&#233;er un nouveau monstre mythique puisqu’il faut pratiquement cr&#233;er un monstre avec deux &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; : un FP initial, qui d&#233;termine son &lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html#RANGMYTHIQUE&quot; title=&quot;Les monstres mythiques&quot;&gt;rang mythique&lt;/a&gt; appropri&#233; et, ainsi, le nombre d’aptitudes mythiques qu’il gagne, et un FP final, qui d&#233;termine les valeurs appropri&#233;es pour sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, ses points de vie, ses d&#233;g&#226;ts par round, etc. M&#234;me s’il est possible de cr&#233;er le monstre en une fois avec un FP et un RMy particulier en t&#234;te, il est g&#233;n&#233;ralement plus facile de proc&#233;der par &#233;tapes (certaines sont tr&#232;s semblables aux &#233;tapes de la modification d’un monstre existant).
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 1 : estimer le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; final.&lt;/b&gt; Il est essentiel de savoir quel est le FP que vous visez pour votre nouveau monstre. Cela vous aidera &#224; d&#233;terminer le niveau de puissance initial de votre monstre lors des &#233;tapes suivantes et vous n’aurez pas &#224; reconfigurez le monstre s’il n’est pas assez puissant ou s’il l’est trop. Par exemple, vous pourriez vouloir cr&#233;er un monstre mythique FP 7 pour mettre un groupe mythique de niveau 5 au d&#233;fi.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 2 : d&#233;terminer le &lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html#RANGMYTHIQUE&quot; title=&quot;Les monstres mythiques&quot;&gt;rang mythique&lt;/a&gt; (RMy).&lt;/b&gt; Divisez le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; final de votre monstre par 2,5 afin d’obtenir son rang mythique approximatif. Si le r&#233;sultat obtenu n’est pas un nombre entier, vous avez toute libert&#233; de choisir le RMy. Par exemple, si votre monstre a un FP final de 7, divisez 7 par 2,5, ce qui vous donne 2,8 : votre monstre peut &#234;tre de rang 2 ou de rang 3. Il est g&#233;n&#233;ralement plus facile de commencer avec un RMy plus bas puisque vous pouvez toujours l’augmenter plus tard si vous avez besoin d’un monstre un peu plus puissant.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 3 : d&#233;terminer le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; initial.&lt;/b&gt; Soustrayez la moiti&#233; du RMy au FP final pour obtenir le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; initial. Si le FP final est de 7 et que le RMy est de 2, 2 divis&#233; par 2 donnant 1, le FP initial est donc de 7-1=6.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 4 : construire un nouveau monstre pour le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; initial.&lt;/b&gt; Cette &#233;tape est identique au processus de cr&#233;ation des monstres &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Nonmythique.html&quot; title=&quot;non-mythique&quot;&gt;non-mythiques&lt;/a&gt;. Suivez les indications du Bestiaire afin de cr&#233;er une cr&#233;ature &#233;quilibr&#233;e pour son FP ou commencez avec une cr&#233;ature de base qui correspond au FP d&#233;sir&#233; et modifiez-la de mani&#232;re &#224; ce qu’elle r&#233;ponde &#224; vos objectifs. Ce sont les trois &#233;tapes suivantes qui font de votre cr&#233;ature un &#234;tre mythique.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 5 : ajouter le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;sous-type mythique&lt;/a&gt;.&lt;/b&gt; Les modifications apport&#233;es aux valeurs de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques.html&quot; title=&quot;Les caract&#233;ristiques&quot;&gt;caract&#233;ristiques&lt;/a&gt; de la cr&#233;ature, &#224; ses points de vie, etc. d&#233;pendent de son RMy.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 6 : ajouter les aptitudes mythiques suppl&#233;mentaires&lt;/b&gt;. Comme indiqu&#233; dans le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;sous-type mythique&lt;/a&gt;, la cr&#233;ature gagne un nombre d’aptitudes mythiques &#233;gal &#224; son RMy +1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;tape 7 : &#233;valuer le monstre avec son &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; final.&lt;/b&gt; Le FP final de votre monstre est &#233;gal &#224; son FP initial + son RMy/2 (ce qui devrait correspondre grosso modo &#224; l’estimation faite &#224; la premi&#232;re &#233;tape). Si le RMy/2 ne donne pas un nombre pair, arrondissez- le &#224; l’inf&#233;rieur pour obtenir le FP final du monstre. Consultez &lt;a class=&quot;pagelink&quot; href=&quot;&#201;valuer-Les-Statistiques-Des-Monstres.html#STATMONSTRESMYTHIQUEPARFP&quot; title=&quot;&#201;valuer les statistiques des monstres&quot;&gt;statistiques des monstres par FP&lt;/a&gt; pour d&#233;terminer si les aptitudes du monstre sont appropri&#233;es au niveau de difficult&#233; correspondant &#224; son FP final. Si les aptitudes mythiques de la cr&#233;ature compl&#232;tent particuli&#232;rement bien ses aptitudes &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Nonmythique.html&quot; title=&quot;non-mythique&quot;&gt;non-mythiques&lt;/a&gt;, alors la cr&#233;ature mythique est sans doute trop puissante pour son FP final. Si les aptitudes mythiques de la cr&#233;ature ne se combinent pas avec ses aptitudes non-mythiques, la cr&#233;ature n’est sans doute pas assez puissante pour son FP final. Si jamais l’un de ces deux cas de figure se pr&#233;sente, proc&#233;dez aux ajustements n&#233;cessaires pour que la cr&#233;ature corresponde au FP vis&#233;. &lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;indent&quot; style=&quot;margin: 0px; padding: 0px; padding-left: 15px&quot;&gt;Si le monstre n’est pas assez puissant et que son RMy de l’&#233;tape 2 n’est pas un nombre entier, augmentez le RMy du monstre de 1 (ajustez les modificateurs apport&#233;s par le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;sous-type mythique&lt;/a&gt;). Si le monstre est trop puissant et que vous devez arrondir &#224; l’inf&#233;rieur pour obtenir son &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; final, comparez le monstre aux statistiques correspondant au FP sup&#233;rieur. Une fois que les aptitudes et statistiques du monstre correspondent &#224; son FP, vous avez termin&#233;.&lt;/div&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre autoalt&quot;&gt;&lt;caption&gt;Aptitudes du sous-type mythique&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Rang mythique&lt;/td&gt;&lt;td&gt;Bonus de caract&#233;ristique&lt;/td&gt;&lt;td&gt;Don mythique&lt;/td&gt;&lt;td&gt;Type de d&#233;s de mont&#233;e en puissance&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;1&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;1er&lt;/td&gt;&lt;td&gt;1d6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;1er&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;1d6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;2e&lt;/td&gt;&lt;td&gt;1d6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;2e&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;1d8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;3e&lt;/td&gt;&lt;td&gt;1d8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;3e&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;1d8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;7&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;4e&lt;/td&gt;&lt;td&gt;1d10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;8&lt;/td&gt;&lt;td&gt;4e&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;1d10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;9&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;5e&lt;/td&gt;&lt;td&gt;1d10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;10&lt;/td&gt;&lt;td&gt;5e&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;1d12&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;POINTSDEVIEMYTHIQUESSUPPLEMENTAIRES&quot; href=&quot;#POINTSDEVIEMYTHIQUESSUPPLEMENTAIRES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Points de vie mythiques suppl&#233;mentaires&lt;a class=&quot;headeranchor&quot; id=&quot;Points_de_vie_mythiques_suppl&#233;mentaires_2&quot; href=&quot;#Points_de_vie_mythiques_suppl&#233;mentaires_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Une cr&#233;ature ayant l’un des &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types-Simples-De-Cr&#233;atures-Mythiques.html&quot; title=&quot;Arch&#233;types simples de cr&#233;atures mythiques&quot;&gt;arch&#233;types simples de cr&#233;atures mythiques&lt;/a&gt; gagne un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;points de vie&lt;/a&gt; suppl&#233;mentaires qui d&#233;pend de son type de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;d&#233;s de vie&lt;/a&gt;. Une cr&#233;ature ayant des d6 pour d&#233;s de vie gagne 6 points de vie par &lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html#RANGMYTHIQUE&quot; title=&quot;Les monstres mythiques&quot;&gt;rang mythique&lt;/a&gt;, une cr&#233;ature qui a pour d&#233;s de vie des d8 gagne 8 points de vie par rang mythique et une cr&#233;ature ayant pour DV des d10 ou des d12 gagne 10 points de vie par rang mythique.
